"""Orientaciones de estudio añadidas con IA en la aplicación; no crean claves."""
NOTES = {}
def add(n, topic, reason, options=None):
    NOTES[n] = {'topic':topic, 'reason':reason, 'options':options}

add(1,'D1-T2-componentes','El material se refiere a los ocho dominios de desempeño del PMBOK 7, no a los cuatro dominios del examen CAPM.', ['Ocho corresponde al contexto PMBOK 7 indicado en el enunciado.','Diez suele asociarse a áreas de conocimiento de otra estructura del PMBOK.','Doce corresponde a los principios del PMBOK 7, no a sus dominios de desempeño.','Cuarenta y nueve se asocia a procesos de la sexta edición, no a dominios.'])
add(2,'D1-T2-componentes','Los dominios de desempeño interactúan durante el proyecto; su aplicación puede ser simultánea y adaptarse al contexto.')
add(3,'D1-T2-componentes','El orden editorial de presentación de los dominios no establece una jerarquía de importancia entre ellos.')
add(4,'D4-T1-identificacion','El dominio de interesados aborda las actividades y funciones relacionadas con involucrar a quienes afectan o reciben los efectos del proyecto.')
add(5,'D4-T1-identificacion','La definición describe a los interesados y contempla influencia real, efectos recibidos y percepción de afectación.', ['La PMO es una oficina con funciones de apoyo o gobierno; no designa a todo el conjunto descrito.','Un área no comprende por sí sola todos los individuos, grupos y organizaciones afectados.','Un proceso es una actividad de gestión, no la persona u organización involucrada.','Interesados es el término que abarca toda la definición.'])
add(6,'D1-T2-registro-interesados','El análisis de interesados organiza información cuantitativa y cualitativa sobre sus intereses, influencia y relación con el proyecto.', ['Un diagrama de influencias representa relaciones entre variables o decisiones.','Un diagrama de afinidad agrupa ideas relacionadas.','La matriz multicriterio compara alternativas mediante criterios; no nombra el análisis completo descrito.','El análisis de interesados permite identificar intereses y orientar el involucramiento.'])
add(7,'D4-T1-identificacion','Los proyectos se realizan con personas y generan resultados para personas; la segunda parte de la afirmación requiere cuestionarse.')
for n in range(8,18):
    add(n,'D4-T1-internos-externos','El dibujo conserva los círculos 1, 2 y 3, pero el documento no define qué conjunto representa cada uno. No es posible asignar un rol a un número sin esa leyenda.', ['El círculo 3 está dibujado, pero su significado no está definido.','El círculo 2 está dibujado, pero su significado no está definido.','El círculo 1 está dibujado, pero su significado no está definido.'])
add(18,'D4-T1-identificacion','La identificación y el involucramiento deben considerar interesados internos y externos; limitar el análisis a los internos deja fuera influencias relevantes.')
add(19,'D1-T3-liderazgo','Las habilidades técnicas se complementan con liderazgo e interacción interpersonal para trabajar con los interesados.')
stages=['Identificar reconoce quién puede afectar o verse afectado.','Comprender y analizar examina intereses, emociones, influencia y relaciones.','Priorizar determina dónde concentrar la atención y el esfuerzo.','Involucrar supone colaborar, comunicar y gestionar expectativas.','Monitorear evalúa cambios y la eficacia del involucramiento.']
add(20,'D1-T2-registro-interesados','El anexo marca identificar, comprender, analizar, priorizar, involucrar y monitorear. El ciclo es iterativo; la figura enumera seis posiciones.', ['Sitúa monitorear antes de analizar y priorizar, alterando la secuencia marcada.','Deja comprender al final, después de la acción y su seguimiento.','Conserva la secuencia de las seis actividades marcada en el anexo.','Comienza por involucrar antes de identificar y comprender.'])
for n,reason in {21:'Identificar puede comenzar antes de formar el equipo y continúa a medida que aparecen interesados.',23:'Comprender y analizar incluye emociones, creencias, valores y cambios que pueden generar amenazas u oportunidades.',25:'Priorizar permite dedicar atención a los interesados cuando no se puede involucrar a todos con la misma intensidad.',26:'Involucrar significa trabajar en colaboración, obtener requisitos, negociar y resolver incidentes.',35:'Monitorear permite comprobar la eficacia del enfoque y ajustarlo cuando cambian los interesados.'}.items():
    add(n,'D1-T2-registro-interesados',reason,stages)
add(22,'D1-T2-registro-interesados','El análisis puede considerar poder, impacto, actitud, creencias, expectativas, influencia, cercanía e interés. El material resuelve la enumeración mediante «Todos los anteriores».', [f'{x} es un aspecto relevante, pero individualmente no recoge toda la lista.' for x in ['Poder','Impacto','Actitud','Creencias','Expectativas','Influencia','Cercanía','Interés']]+['La alternativa reúne los ocho aspectos enumerados.'])
add(24,'D1-T2-registro-interesados','Las relaciones entre interesados pueden generar alianzas, conflictos y nuevas influencias; deben considerarse en el análisis.')
